INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('1','launch-1','Welcome to Digimon NXT','The NXT Network is online. Explore the eleven native-resolution Cyberspace sectors, battle wild Digimon, recover scan data and materialize new partners.','system','1788554863','1');
INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('2','launch-2','DigiLab Materialization Protocol','Scan data is species-specific. Reach 100% scan data to materialize a persistent Digimon instance. Conversion uses all accumulated scan data. Every 20% above 100% grants 1 starting ABI, up to 5 at 200%.','research','1788641263','1');
INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('3','launch-3','Paradox Signals Detected','The roster now contains 1,000 supplied forms. Paradox signals have a 0.2% chance per wild encounter, 1.75 times base stats, and yield only 1–3% scan data. Use capsule recovery during battle, and build ABI through evolution.','research','1788727663','1');
INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('4','launch-4','Multiplayer Presence Active','Tamers sharing the same Cyberspace sector are synchronized through the map presence service. Movement remains server validated against the sector collision grid.','network','1788814063','1');
INSERT INTO `events` (`id`,`slug`,`name`,`area_name`,`description`,`starts_at`,`ends_at`,`is_active`) VALUES ('1','cyber-route-sweep','Cyber Route Sweep','Cyber Route','Defeat wild Digimon along Cyber Route to stabilize corrupted packet clusters.','0','0','1');
INSERT INTO `events` (`id`,`slug`,`name`,`area_name`,`description`,`starts_at`,`ends_at`,`is_active`) VALUES ('2','icewall-breach','Icewall Breach','Icewall','Push through Icewall and recover DigiCore Fragments from hostile signatures.','0','0','1');
INSERT INTO `events` (`id`,`slug`,`name`,`area_name`,`description`,`starts_at`,`ends_at`,`is_active`) VALUES ('3','the-core-protocol','The Core Protocol','The Core','A high-level network challenge centered on the deepest accessible sector of Cyberspace.','0','0','1');
